'use client';
import { useState } from 'react';
import styles from './page.module.css';

export default function Home() {
  const [messages, setMessages] = useState([
    { role: 'ai', content: 'Hello! I am OmniAI. How can I help you today? I can chat, generate images, or create documents.' }
  ]);
  const [input, setInput] = useState('');
  const [mode, setMode] = useState('chat'); // 'chat', 'image', 'document'
  const [tokens, setTokens] = useState(10); // Mock tokens

  const handleSend = async () => {
    if (!input.trim()) return;

    const userMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');

    // Simulate token deduction based on mode
    let tokenCost = mode === 'chat' ? 1 : mode === 'image' ? 3 : 5;

    if (tokens < tokenCost) {
      setMessages(prev => [...prev, { role: 'ai', content: 'Not enough tokens for this action. Please upgrade to Premium.' }]);
      return;
    }

    setTokens(prev => prev - tokenCost);

    // Simulate API call delay
    setTimeout(() => {
      let aiResponse = '';
      if (mode === 'chat') aiResponse = `This is a mock response from OmniAI for: "${userMessage.content}"`;
      if (mode === 'image') aiResponse = `[Image generated for: "${userMessage.content}"]`;
      if (mode === 'document') aiResponse = `[Document generated based on: "${userMessage.content}". Click here to download.]`;

      setMessages(prev => [...prev, { role: 'ai', content: aiResponse }]);
    }, 1000);
  };

  return (
    <div className={styles.container}>
      {/* Sidebar */}
      <div className={styles.sidebar}>
        <div className={styles.logo}>OmniAI</div>

        <div className={styles.tokenInfo}>
          <div>Daily Tokens Remaining</div>
          <div className={styles.tokenCount}>{tokens} / 10</div>
          <div style={{ fontSize: '0.8rem', marginTop: '5px', color: 'var(--text-muted)' }}>
            Chat: 1 | Image: 3 | Doc: 5
          </div>
        </div>
      </div>

      {/* Main Content */}
      <div className={styles.main}>
        <div className={styles.header}>
          <h2>{mode.charAt(0).toUpperCase() + mode.slice(1)} Mode</h2>
        </div>

        <div className={styles.chatArea}>
          {messages.map((msg, idx) => (
            <div key={idx} className={`${styles.message} ${msg.role === 'user' ? styles.userMessage : styles.aiMessage}`}>
              {msg.content}
            </div>
          ))}
        </div>

        <div className={styles.inputArea}>
          <div className={styles.controls}>
            <button 
              className={`${styles.controlBtn} ${mode === 'chat' ? styles.active : ''}`}
              onClick={() => setMode('chat')}
            >💬 Chat (1 Token)</button>
            <button 
              className={`${styles.controlBtn} ${mode === 'image' ? styles.active : ''}`}
              onClick={() => setMode('image')}
            >🖼️ Image (3 Tokens)</button>
            <button 
              className={`${styles.controlBtn} ${mode === 'document' ? styles.active : ''}`}
              onClick={() => setMode('document')}
            >📄 Document (5 Tokens)</button>
          </div>
          <div style={{height: '15px'}}></div>
          <div className={styles.inputWrapper}>
            <input 
              type="text" 
              className={styles.input} 
              placeholder={`Type your prompt for ${mode}...`}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && handleSend()}
            />
            <button className={styles.button} onClick={handleSend}>Send</button>
          </div>
        </div>
      </div>
    </div>
  );
}

