'use client';
import { useState, useEffect, useRef } from 'react';
import { useRouter } from 'next/navigation';
import { supabase } from '../lib/supabase';
import styles from './page.module.css';
import ReactMarkdown from 'react-markdown';
import { Prism as SyntaxHighlighter } from 'react-syntax-highlighter';
import { oneDark } from 'react-syntax-highlighter/dist/cjs/styles/prism';

/* ─── Code Block with Copy Button ─── */
function CodeBlock({ language, children }) {
  const [copied, setCopied] = useState(false);

  const handleCopy = async () => {
    try {
      await navigator.clipboard.writeText(String(children));
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    } catch (err) {
      console.error('Copy failed:', err);
    }
  };

  return (
    <div className={styles.codeBlockContainer}>
      <div className={styles.codeBlockHeader}>
        <span className={styles.codeLanguage}>{language || 'code'}</span>
        <button
          className={`${styles.copyButton} ${copied ? styles.copyButtonCopied : ''}`}
          onClick={handleCopy}
        >
          {copied ? '✓ Copied!' : '📋 Copy'}
        </button>
      </div>
      <SyntaxHighlighter
        language={language}
        style={oneDark}
        customStyle={{
          margin: 0,
          padding: '16px',
          borderRadius: '0 0 8px 8px',
          fontSize: '0.88rem',
          background: '#1a1b26',
        }}
        wrapLongLines={true}
      >
        {String(children).replace(/\n$/, '')}
      </SyntaxHighlighter>
    </div>
  );
}

/* ─── Main App ─── */
export default function Home() {
  const router = useRouter();
  const [session, setSession] = useState(null);
  const [messages, setMessages] = useState([
    { role: 'ai', content: 'Hello! I am **OmniAI** 🚀. How can I help you today? I can chat, generate images, or create documents.' }
  ]);
  const [input, setInput] = useState('');
  const [mode, setMode] = useState('chat');
  const [tokens, setTokens] = useState(0);
  const [isStreaming, setIsStreaming] = useState(false);
  const abortControllerRef = useRef(null);
  const chatAreaRef = useRef(null);

  /* Auto-scroll to bottom on new messages */
  useEffect(() => {
    if (chatAreaRef.current) {
      chatAreaRef.current.scrollTop = chatAreaRef.current.scrollHeight;
    }
  }, [messages]);

  /* Auth check */
  useEffect(() => {
    supabase.auth.getSession().then(({ data: { session } }) => {
      if (!session) {
        router.push('/login');
      } else {
        setSession(session);
        fetchTokens(session.user.id);
      }
    });

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (!session) router.push('/login');
      setSession(session);
    });

    return () => subscription.unsubscribe();
  }, [router]);

  const fetchTokens = async (userId) => {
    const { data } = await supabase
      .from('users')
      .select('tokens')
      .eq('id', userId)
      .single();
    if (data) setTokens(data.tokens);
  };

  const handleLogout = async () => {
    await supabase.auth.signOut();
  };

  /* ─── Stop Streaming ─── */
  const handleStop = () => {
    if (abortControllerRef.current) {
      abortControllerRef.current.abort();
      abortControllerRef.current = null;
      setIsStreaming(false);
    }
  };

  /* ─── Send Message ─── */
  const handleSend = async () => {
    if (!input.trim() || !session || isStreaming) return;

    const userMessage = { role: 'user', content: input };
    const updatedMessages = [...messages, userMessage];
    setMessages(updatedMessages);
    setInput('');

    const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';

    /* ── Image & Document modes (non-streaming) ── */
    if (mode !== 'chat') {
      const endpoint = mode === 'image' ? '/api/image' : '/api/document';
      const payload = mode === 'image'
        ? { prompt: userMessage.content }
        : { topic: userMessage.content, doc_type: 'word' };

      try {
        const response = await fetch(`${apiUrl}${endpoint}`, {
          method: 'POST',
          headers: {
            'Content-Type': 'application/json',
            'Authorization': `Bearer ${session.access_token}`
          },
          body: JSON.stringify(payload)
        });

        if (!response.ok) {
          setMessages(prev => [...prev, { role: 'ai', content: response.status === 402 ? 'Insufficient Credits.' : 'An error occurred.' }]);
          return;
        }

        const data = await response.json();
        let aiContent = '';
        if (mode === 'image') aiContent = `![Generated Image](${apiUrl}${data.image_url})`;
        if (mode === 'document') aiContent = `📄 [Download Document](${apiUrl}${data.file_url})`;
        setMessages(prev => [...prev, { role: 'ai', content: aiContent }]);
        setTokens(prev => prev - (mode === 'image' ? 3 : 5));
      } catch (error) {
        setMessages(prev => [...prev, { role: 'ai', content: `Error: ${error.message}` }]);
      }
      return;
    }

    /* ── Chat mode: STREAMING ── */
    const chatHistory = updatedMessages.slice(-10).map(m => ({
      role: m.role === 'ai' ? 'assistant' : 'user',
      content: m.content
    }));

    const controller = new AbortController();
    abortControllerRef.current = controller;
    setIsStreaming(true);

    // Add empty AI placeholder that fills up progressively
    setMessages(prev => [...prev, { role: 'ai', content: '' }]);

    try {
      const response = await fetch(`${apiUrl}/api/chat/stream`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${session.access_token}`
        },
        body: JSON.stringify({ messages: chatHistory }),
        signal: controller.signal
      });

      if (!response.ok) {
        const errorText = await response.text();
        setMessages(prev => {
          const updated = [...prev];
          updated[updated.length - 1] = { role: 'ai', content: `Error ${response.status}: ${errorText}` };
          return updated;
        });
        return;
      }

      const reader = response.body.getReader();
      const decoder = new TextDecoder();
      let buffer = '';

      while (true) {
        const { done, value } = await reader.read();
        if (done) break;

        buffer += decoder.decode(value, { stream: true });
        const lines = buffer.split('\n');
        buffer = lines.pop() || '';

        for (const line of lines) {
          const trimmed = line.trim();
          if (trimmed.startsWith('data: ')) {
            const data = trimmed.slice(6);
            if (data === '[DONE]') continue;
            try {
              const parsed = JSON.parse(data);
              if (parsed.token) {
                setMessages(prev => {
                  const updated = [...prev];
                  const lastMsg = updated[updated.length - 1];
                  updated[updated.length - 1] = {
                    ...lastMsg,
                    content: lastMsg.content + parsed.token
                  };
                  return updated;
                });
              }
            } catch { /* skip malformed chunks */ }
          }
        }
      }

      setTokens(prev => prev - 1);
    } catch (error) {
      if (error.name !== 'AbortError') {
        setMessages(prev => {
          const updated = [...prev];
          const lastMsg = updated[updated.length - 1];
          if (lastMsg && lastMsg.content === '') {
            updated[updated.length - 1] = { role: 'ai', content: `Error: ${error.message}` };
          }
          return updated;
        });
      }
    } finally {
      setIsStreaming(false);
      abortControllerRef.current = null;
    }
  };

  /* ─── Markdown Components Config ─── */
  const markdownComponents = {
    code({ node, inline, className, children, ...props }) {
      const match = /language-(\w+)/.exec(className || '');
      return !inline && match ? (
        <CodeBlock language={match[1]}>{children}</CodeBlock>
      ) : (
        <code {...props} className={`${className || ''} ${styles.inlineCode}`}>
          {children}
        </code>
      );
    }
  };

  if (!session) {
    return (
      <div className={styles.container} style={{ justifyContent: 'center', alignItems: 'center' }}>
        <div className={styles.loadingSpinner}></div>
      </div>
    );
  }

  return (
    <div className={styles.container}>
      {/* ── Sidebar ── */}
      <div className={styles.sidebar}>
        <div className={styles.logo}>
          <span className={styles.logoIcon}>⚡</span> OmniAI
        </div>

        <div className={styles.sidebarContent}>
          <p style={{ color: 'var(--text-muted)', fontSize: '0.85rem', textAlign: 'center' }}>
            Chat history coming soon...
          </p>
        </div>

        <div className={styles.tokenInfo}>
          <div style={{ fontSize: '0.8rem', color: 'var(--text-muted)' }}>Daily Tokens</div>
          <div className={styles.tokenCount}>{tokens} / 10</div>
          <div style={{ fontSize: '0.75rem', marginTop: '5px', color: 'var(--text-muted)' }}>
            Chat: 1 | Image: 3 | Doc: 5
          </div>
        </div>
        <button className={styles.logoutBtn} onClick={handleLogout}>
          🚪 Logout
        </button>
      </div>

      {/* ── Main Content ── */}
      <div className={styles.main}>
        <div className={styles.header}>
          <h2 className={styles.headerTitle}>
            {mode === 'chat' ? '💬' : mode === 'image' ? '🖼️' : '📄'} {mode.charAt(0).toUpperCase() + mode.slice(1)} Mode
          </h2>
          <div className={styles.modelBadge}>⚡ Groq Llama 3.1</div>
        </div>

        <div className={styles.chatArea} ref={chatAreaRef}>
          {messages.map((msg, idx) => (
            <div key={idx} className={`${styles.message} ${msg.role === 'user' ? styles.userMessage : styles.aiMessage}`}>
              {msg.role === 'ai' ? (
                <div className={styles.aiContent}>
                  <ReactMarkdown components={markdownComponents}>
                    {msg.content || ' '}
                  </ReactMarkdown>
                  {isStreaming && idx === messages.length - 1 && (
                    <span className={styles.streamingCursor}>▌</span>
                  )}
                </div>
              ) : (
                <span>{msg.content}</span>
              )}
            </div>
          ))}
        </div>

        <div className={styles.inputArea}>
          <div className={styles.controls}>
            <button
              className={`${styles.controlBtn} ${mode === 'chat' ? styles.active : ''}`}
              onClick={() => setMode('chat')}
            >💬 Chat (1 Token)</button>
            <button
              className={`${styles.controlBtn} ${mode === 'image' ? styles.active : ''}`}
              onClick={() => setMode('image')}
            >🖼️ Image (3 Tokens)</button>
            <button
              className={`${styles.controlBtn} ${mode === 'document' ? styles.active : ''}`}
              onClick={() => setMode('document')}
            >📄 Document (5 Tokens)</button>
          </div>
          <div style={{ height: '12px' }}></div>
          <div className={styles.inputWrapper}>
            <input
              type="text"
              className={styles.input}
              placeholder={isStreaming ? 'AI is responding...' : `Type your prompt for ${mode}...`}
              value={input}
              onChange={(e) => setInput(e.target.value)}
              onKeyDown={(e) => e.key === 'Enter' && !isStreaming && handleSend()}
              disabled={isStreaming}
            />
            {isStreaming ? (
              <button className={styles.stopButton} onClick={handleStop}>
                <span className={styles.stopIcon}>■</span> Stop
              </button>
            ) : (
              <button className={styles.sendButton} onClick={handleSend}>
                Send <span style={{ marginLeft: '4px' }}>→</span>
              </button>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}

