const recognitionRef = useRef(null);

/* Menu Action Handlers */
const handleFileUpload = () => {
  setIsAttachmentMenuOpen(false);
  if (fileInputRef.current) {
    fileInputRef.current.click();
  }
};

const handleGenerateImage = async (prompt) => {
  if (!prompt.trim()) return;
  try {
    const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
    const response = await fetch(`${apiUrl}/api/generate-image`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session?.access_token}` },
      body: JSON.stringify({ prompt })
    });
    console.log('Image Generation Response:', response);
  } catch (error) {
    console.error('Image Gen Error:', error);
  }
};

const handleCreatePresentation = async (prompt) => {
  if (!prompt.trim()) return;
  try {
    const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
    const response = await fetch(`${apiUrl}/api/generate-presentation`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'Authorization': `Bearer ${session?.access_token}` },
      body: JSON.stringify({ topic: prompt, doc_type: 'presentation' })
    });
    console.log('Presentation Generation Response:', response);
  } catch (error) {
    console.error('Presentation Gen Error:', error);
  }
};

const triggerImageGen = () => {
  setIsAttachmentMenuOpen(false);
  handleGenerateImage(input);
  setInput('');
};

const triggerPresentationGen = () => {
  setIsAttachmentMenuOpen(false);
  handleCreatePresentation(input);
  setInput('');
};

/* Speech Recognition */
const toggleListening = () => {
  if (isListening) {
    if (recognitionRef.current) recognitionRef.current.stop();
    setIsListening(false);
    return;
  }

  const SpeechRecognition = window.SpeechRecognition || window.webkitSpeechRecognition;
  if (!SpeechRecognition) {
    alert("Speech recognition is not supported in this browser.");
    return;
  }

  const recognition = new SpeechRecognition();
  recognition.continuous = false;
  recognition.interimResults = false;
  recognitionRef.current = recognition;

  recognition.onstart = () => setIsListening(true);
  recognition.onresult = (event) => {
    let finalTranscript = '';
    for (let i = event.resultIndex; i < event.results.length; ++i) {
      if (event.results[i].isFinal) {
        finalTranscript += event.results[i][0].transcript;
      }
    }
    if (finalTranscript) {
      setInput((prev) => prev + (prev ? ' ' : '') + finalTranscript);
    }
  };
  recognition.onerror = (e) => console.error("Speech Rec Error:", e);
  recognition.onend = () => setIsListening(false);
  recognition.start();
};

