const executeStreamRequest = async (chatHistory, isRetry = false) => {
  const controller = new AbortController();
  const timeoutId = setTimeout(() => controller.abort(new Error("Timeout")), 30000);
  abortControllerRef.current = controller;

  if (isRetry) {
    setMessages(prev => {
      const updated = [...prev];
      updated[updated.length - 1] = { role: 'ai', content: '⏳ *Retrying...*' };
      return updated;
    });
  } else {
    setMessages(prev => [...prev, { role: 'ai', content: '' }]);
  }

  setIsStreaming(true);
  let finalContent = '';
  let success = false;
  let hasYielded = false;

  try {
    const apiUrl = process.env.NEXT_PUBLIC_API_URL || 'http://localhost:8000';
    const response = await fetch(`${apiUrl}/api/chat/stream`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Authorization': `Bearer ${session?.access_token}`
      },
      body: JSON.stringify({ messages: chatHistory }),
      signal: controller.signal
    });

    clearTimeout(timeoutId);

    if (!response.ok) {
      const errorText = await response.text();
      throw new Error(`HTTP ${response.status}: ${errorText}`);
    }

    const reader = response.body.getReader();
    const decoder = new TextDecoder();
    let buffer = '';

    while (true) {
      const { done, value } = await reader.read();
      if (done) break;

      buffer += decoder.decode(value, { stream: true });
      const lines = buffer.split('\n');
      buffer = lines.pop() || '';

      for (const line of lines) {
        const trimmed = line.trim();
        if (trimmed.startsWith('data: ')) {
          const data = trimmed.slice(6);
          if (data === '[DONE]') continue;
          try {
            const parsed = JSON.parse(data);
            if (parsed.token) {
              if (!hasYielded && isRetry) {
                // Clear the "Retrying..." text on first real token
                finalContent = '';
              }
              hasYielded = true;
              finalContent += parsed.token;
              setMessages(prev => {
                const updated = [...prev];
                const lastMsg = updated[updated.length - 1];
                updated[updated.length - 1] = {
                  ...lastMsg,
                  content: (!hasYielded && isRetry) ? parsed.token : (isRetry && lastMsg.content === '⏳ *Retrying...*' ? parsed.token : lastMsg.content + parsed.token),
                  isError: false,
                  chatHistory: chatHistory // store for manual retry
                };
                return updated;
              });
            }
          } catch { /* skip malformed chunks */ }
        }
      }
    }
    success = true;
  } catch (error) {
    clearTimeout(timeoutId);
    let errorMsg = error.message;
    if (error.name === 'AbortError' || error.message === 'Timeout') {
      errorMsg = "Request timed out (30s).";
    } else if (!errorMsg) {
      errorMsg = "Provider returned an error.";
    }

    finalContent = `\n\n**Error:** ${errorMsg}`;
    setMessages(prev => {
      const updated = [...prev];
      const lastMsg = updated[updated.length - 1];
      const prevContent = lastMsg.content.replace('⏳ *Retrying...*', '');
      updated[updated.length - 1] = { 
        role: 'ai', 
        content: prevContent + finalContent,
        isError: true,
        chatHistory: chatHistory // store for manual retry
      };
      return updated;
    });
  } finally {
    setIsStreaming(false);
    abortControllerRef.current = null;
  }

  return { success, finalContent };
};

const handleManualRetry = async (idx) => {
  const msg = messages[idx];
  if (!msg.chatHistory || isStreaming) return;

  // Remove the errored message
  setMessages(prev => prev.slice(0, idx));

  let { success, finalContent } = await executeStreamRequest(msg.chatHistory, true);
  if (success && finalContent.trim() !== '') {
     setTokens(prev => prev - 1);
  }
};

