'use client';
import { useState, useEffect } from 'react';
import styles from '../auth.module.css';
import { useRouter } from 'next/navigation';
import { API_URL } from '../../lib/apiClient';

export default function Login() {
  const router = useRouter();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  // UI State
  const [showEmailForm, setShowEmailForm] = useState(false);

  useEffect(() => {
    const token = localStorage.getItem('access_token');
    if (token) {
      router.push('/');
    }
  }, [router]);

  const handleEmailLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');
    try {
      const response = await fetch(`${API_URL}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email, password })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Login failed');
      }

      if (data.data?.access_token && data.data?.refresh_token) {
        localStorage.setItem('access_token', data.data.access_token);
        localStorage.setItem('refresh_token', data.data.refresh_token);
        router.push('/');
      } else {
        throw new Error('Invalid response from server');
      }
    } catch (err) {
      console.error('Error logging in:', err.message);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  const handleGoogleLogin = async () => {
    // In production, this would open Google OAuth popup or redirect
    // and then send the resulting id_token to our backend
    console.log("Google Login Clicked");
    router.push('/auth/google-callback'); // Mock routing or implement Firebase
  };

  return (
    <div className={styles.authContainer}>
      <div className={styles.authCard}>
        <div className={styles.authLogo}>OmniAI</div>
        <div className={styles.authSubtitle}>Welcome back. Continue to your account.</div>

        {error && <div className={styles.errorMsg}>{error}</div>}

        {!showEmailForm ? (
          <>
            <button className={styles.authSocialBtn} onClick={handleGoogleLogin}>
              <svg width="20" height="20" viewBox="0 0 24 24">
                <path d="M22.56 12.25c0-.78-.07-1.53-.2-2.25H12v4.26h5.92c-.26 1.37-1.04 2.53-2.21 3.31v2.77h3.57c2.08-1.92 3.28-4.74 3.28-8.09z" fill="#4285F4"/>
                <path d="M12 23c2.97 0 5.46-.98 7.28-2.66l-3.57-2.77c-.98.66-2.23 1.06-3.71 1.06-2.86 0-5.29-1.93-6.16-4.53H2.18v2.84C3.99 20.53 7.7 23 12 23z" fill="#34A853"/>
                <path d="M5.84 14.09c-.22-.66-.35-1.36-.35-2.09s.13-1.43.35-2.09V7.07H2.18C1.43 8.55 1 10.22 1 12s.43 3.45 1.18 4.93l2.85-2.22.81-.62z" fill="#FBBC05"/>
                <path d="M12 5.38c1.62 0 3.06.56 4.21 1.64l3.15-3.15C17.45 2.09 14.97 1 12 1 7.7 1 3.99 3.47 2.18 7.07l3.66 2.84c.87-2.6 3.3-4.53 6.16-4.53z" fill="#EA4335"/>
              </svg>
              Continue with Google
            </button>
            <button className={styles.authSocialBtn} onClick={() => router.push('/phone-login')}>
              <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
                <path d="M22 16.92v3a2 2 0 0 1-2.18 2 19.79 19.79 0 0 1-8.63-3.07 19.5 19.5 0 0 1-6-6 19.79 19.79 0 0 1-3.07-8.67A2 2 0 0 1 4.11 2h3a2 2 0 0 1 2 1.72 12.84 12.84 0 0 0 .7 2.81 2 2 0 0 1-.45 2.11L8.09 9.91a16 16 0 0 0 6 6l1.27-1.27a2 2 0 0 1 2.11-.45 12.84 12.84 0 0 0 2.81.7A2 2 0 0 1 22 16.92z"></path>
              </svg>
              Continue with Phone
            </button>

            <div className={styles.authDivider}>or</div>

            <button className={styles.authButton} onClick={() => setShowEmailForm(true)} style={{ marginTop: '0' }}>
              Continue with Email
            </button>
          </>
        ) : (
          <form onSubmit={handleEmailLogin} className={styles.authForm}>
            <input 
              type="email" 
              placeholder="Email address" 
              value={email}
              onChange={(e) => setEmail(e.target.value)}
              className={styles.authInput}
              required
            />
            <input 
              type="password" 
              placeholder="Password" 
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className={styles.authInput}
              required
            />
            <button 
              type="submit"
              className={styles.authButton} 
              disabled={loading}
            >
              {loading ? 'Logging in...' : 'Sign In'}
            </button>

            <button type="button" className={styles.authLink} onClick={() => setShowEmailForm(false)} style={{ marginTop: '10px' }}>
              Back to all options
            </button>
          </form>
        )}

        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '25px', padding: '0 10px' }}>
          <button className={styles.authLink} onClick={() => router.push('/forgot-password')}>Forgot password?</button>
          <button className={styles.authLink} onClick={() => router.push('/register')}>Sign up</button>
        </div>
      </div>
    </div>
  );
}

