'use client';
import { useState } from 'react';
import styles from '../auth.module.css';
import { useRouter } from 'next/navigation';
import { API_URL } from '../../lib/apiClient';

export default function PhoneLogin() {
  const router = useRouter();
  const [phoneNumber, setPhoneNumber] = useState('');
  const [otp, setOtp] = useState('');
  const [step, setStep] = useState(1); // 1 = Phone, 2 = OTP
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleSendCode = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      // In a real app, this would use Firebase Recaptcha and signInWithPhoneNumber
      // Since we don't have Firebase credentials, we mock the UI flow.
      setTimeout(() => {
        setStep(2);
        setLoading(false);
      }, 1000);
    } catch (err) {
      setError('Failed to send verification code');
      setLoading(false);
    }
  };

  const handleVerifyOTP = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      // In a real app, we would verify the OTP with Firebase, get the user, and get the Firebase ID token.
      // Here we send a mock token to the FastAPI backend to complete the flow.
      const mockFirebaseToken = 'mock_firebase_token_' + phoneNumber;

      const response = await fetch(`${API_URL}/auth/phone`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ id_token: mockFirebaseToken })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.message || 'Phone login failed');
      }

      if (data.data?.access_token) {
        localStorage.setItem('access_token', data.data.access_token);
        localStorage.setItem('refresh_token', data.data.refresh_token);
        router.push('/');
      } else {
        throw new Error('Invalid response from server');
      }
    } catch (err) {
      console.error('Phone Auth Error:', err.message);
      setError(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className={styles.authContainer}>
      <div className={styles.authCard}>
        <div className={styles.authLogo}>OmniAI</div>
        <div className={styles.authSubtitle}>Continue with your phone number.</div>

        {error && <div className={styles.errorMsg}>{error}</div>}

        {step === 1 ? (
          <form onSubmit={handleSendCode} className={styles.authForm}>
            <input 
              type="tel" 
              placeholder="Phone Number (e.g. +1234567890)" 
              value={phoneNumber}
              onChange={(e) => setPhoneNumber(e.target.value)}
              className={styles.authInput}
              required
            />
            <button 
              type="submit"
              className={styles.authButton} 
              disabled={loading}
            >
              {loading ? 'Sending...' : 'Send Verification Code'}
            </button>
            <div style={{ textAlign: 'center', marginTop: '15px' }}>
              <button type="button" className={styles.authLink} onClick={() => router.push('/login')}>Back to Sign In</button>
            </div>
          </form>
        ) : (
          <form onSubmit={handleVerifyOTP} className={styles.authForm}>
            <input 
              type="tel" 
              placeholder="Phone Number" 
              value={phoneNumber}
              className={styles.authInput}
              disabled
            />
            <input 
              type="text" 
              placeholder="Enter 6-digit code" 
              value={otp}
              onChange={(e) => setOtp(e.target.value)}
              className={styles.authInput}
              required
              maxLength={6}
              style={{ textAlign: 'center', letterSpacing: '4px', fontSize: '1.1rem', fontWeight: 'bold' }}
            />
            <button 
              type="submit"
              className={styles.authButton} 
              disabled={loading}
            >
              {loading ? 'Verifying...' : 'Verify & Sign In'}
            </button>
            <div style={{ textAlign: 'center', marginTop: '15px' }}>
              <button type="button" className={styles.authLink} onClick={() => setStep(1)}>Change Phone Number</button>
            </div>
          </form>
        )}
      </div>
    </div>
  );
}

