'use client';
import { useState, Suspense } from 'react';
import styles from '../auth.module.css';
import { useRouter, useSearchParams } from 'next/navigation';
import { API_URL } from '../../lib/apiClient';

function EmailPasswordForm() {
  const router = useRouter();
  const searchParams = useSearchParams();
  const emailParam = searchParams.get('email') || '';

  const [password, setPassword] = useState('');
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      const response = await fetch(`${API_URL}/auth/login`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: emailParam, password })
      });

      const data = await response.json();

      if (!response.ok) {
        // If they don't have an account or invalid password
        if (data.message === "Invalid email or password" || data.message === "User not found") {
           setError('Invalid password. If you do not have an account, please sign up.');
        } else {
           setError(data.message || 'Login failed');
        }
        setLoading(false);
        return;
      }

      if (data.data?.access_token) {
        localStorage.setItem('access_token', data.data.access_token);
        localStorage.setItem('refresh_token', data.data.refresh_token);
        router.push('/');
      } else {
        throw new Error('Invalid response from server');
      }
    } catch (err) {
      console.error('Login Error:', err.message);
      setError(err.message);
      setLoading(false);
    }
  };

  return (
    <div className={styles.authContainer}>
      <div className={styles.authModal}>
        <button className={styles.closeButton} onClick={() => router.push('/login')}>←</button>

        <h1 className={styles.title}>Enter your password</h1>
        <p className={styles.subtitle}>{emailParam}</p>

        {error && <div className={styles.errorMsg}>{error}</div>}

        <form onSubmit={handleLogin}>
          <input 
            type="password" 
            placeholder="Password" 
            value={password}
            onChange={(e) => setPassword(e.target.value)}
            className={styles.inputField}
            required
            autoFocus
          />
          <button 
            type="submit"
            className={styles.primaryButton} 
            disabled={loading}
          >
            {loading ? 'Logging in...' : 'Continue'}
          </button>
        </form>

        <div style={{ display: 'flex', justifyContent: 'space-between', marginTop: '24px' }}>
          <button className={styles.link} onClick={() => router.push('/forgot-password')}>Forgot password?</button>
          <button className={styles.link} onClick={() => router.push('/register')}>Sign up instead</button>
        </div>
      </div>
    </div>
  );
}

export default function EmailPassword() {
  return (
    <Suspense fallback={<div className={styles.authContainer}>Loading...</div>}>
      <EmailPasswordForm />
    </Suspense>
  );
}

