'use client';
import { useState, Suspense, useEffect } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import { motion } from 'framer-motion';
import { useAuth } from '../../context/AuthContext';
import { auth } from '../../lib/firebase';
import { signInWithEmailAndPassword, createUserWithEmailAndPassword, sendPasswordResetEmail } from 'firebase/auth';
import { API_URL } from '../../lib/apiClient';

function EmailPasswordForm({ isModal }) {
  const router = useRouter();
  const searchParams = useSearchParams();
  const { login } = useAuth();

  const [emailState, setEmailState] = useState('');
  const [password, setPassword] = useState('');
  const [isSignUp, setIsSignUp] = useState(false);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState('');
  const [resetSent, setResetSent] = useState(false);

  useEffect(() => {
    const e = searchParams.get('email');
    if (e) setEmailState(e);
  }, [searchParams]);

  const handleLogin = async (e) => {
    e.preventDefault();
    setLoading(true);
    setError('');

    try {
      let userCredential;
      if (isSignUp) {
        userCredential = await createUserWithEmailAndPassword(auth, emailState, password);
      } else {
        userCredential = await signInWithEmailAndPassword(auth, emailState, password);
      }

      const idToken = await userCredential.user.getIdToken();

      const response = await fetch(`${API_URL}/api/auth/firebase`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token: idToken })
      });

      const data = await response.json();

      if (!response.ok) {
        throw new Error(data.detail || 'Backend authentication failed');
      }

      await login(data.data.access_token);

      if (isModal) {
        router.back();
      } else {
        router.push('/');
      }
    } catch (err) {
      console.error('Login Error:', err.message);
      if (err.code === 'auth/user-not-found' || err.code === 'auth/wrong-password' || err.code === 'auth/invalid-credential') {
         setError('Invalid email or password.');
      } else if (err.code === 'auth/email-already-in-use') {
         setError('Email already in use. Please sign in instead.');
      } else {
         setError(err.message || 'Authentication failed.');
      }
    } finally {
      setLoading(false);
    }
  };

  const handleResetPassword = async () => {
    if (!emailState) return;
    try {
      await sendPasswordResetEmail(auth, emailState);
      setResetSent(true);
    } catch (err) {
      setError(err.message);
    }
  };

  return (
    <div className="fixed inset-0 flex flex-col items-center justify-center min-h-screen w-full bg-black/60 backdrop-blur-sm text-white z-[100] font-sans">
      <motion.div 
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ duration: 0.4, ease: "easeOut" }}
        className="w-full max-w-[420px] relative z-10 flex flex-col items-center"
      >
        <div className="bg-[#202123] rounded-[24px] p-8 shadow-2xl flex flex-col items-center w-full">
          <button className="absolute top-5 right-5 text-gray-400 hover:text-white" onClick={() => router.back()}>✕</button>

          <h1 className="text-[28px] font-bold mb-3 mt-4">{isSignUp ? 'Create an account' : 'Enter your password'}</h1>

          <p className="text-gray-300 mb-8 text-center text-[16px]">{emailState}</p>

          {error && <div className="text-red-500 mb-4 text-sm text-center">{error}</div>}
          {resetSent && <div className="text-green-500 mb-4 text-sm text-center">Password reset email sent!</div>}

          <form onSubmit={handleLogin} className="w-full flex flex-col gap-6">
            <div className="relative w-full">
              <input 
                type="password" 
                id="passwordInput"
                value={password}
                onChange={(e) => setPassword(e.target.value)}
                className="w-full bg-transparent border border-[#7a82da] rounded-full px-5 py-4 text-white focus:outline-none transition peer placeholder-transparent"
                placeholder="Password"
                required
                autoFocus
              />
              <label htmlFor="passwordInput" className="absolute left-4 -top-3 bg-[#202123] px-1 text-[13px] text-[#7a82da] peer-placeholder-shown:text-gray-400 peer-placeholder-shown:top-4 peer-focus:-top-3 peer-focus:text-[#7a82da] transition-all cursor-text">
                Password
              </label>
            </div>

            <button 
              type="submit"
              className={`w-full text-black font-semibold py-4 px-4 rounded-full transition text-[16px] ${loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-white hover:bg-gray-200'}`}
              disabled={loading}
            >
              {loading ? (isSignUp ? 'Signing up...' : 'Logging in...') : 'Continue'}
            </button>
          </form>

          {!isSignUp && (
            <button className="text-gray-400 font-medium hover:text-white mt-6 text-sm" onClick={handleResetPassword} type="button">
              Forgot password?
            </button>
          )}

          <div className="flex w-full items-center text-gray-500 my-8">
            <div className="flex-1 border-t border-gray-600"></div>
            <span className="px-4 text-[12px] font-bold text-white">OR</span>
            <div className="flex-1 border-t border-gray-600"></div>
          </div>

          <button 
            className="w-full bg-transparent border border-gray-600 text-white font-semibold py-4 px-4 rounded-full hover:bg-[#2A2B32] transition text-[16px]"
            onClick={() => setIsSignUp(!isSignUp)}
            type="button"
          >
            {isSignUp ? 'Sign in instead' : 'Sign up instead'}
          </button>
        </div>
      </motion.div>
    </div>
  );
}

export default function EmailPassword({ isModal }) {
  return (
    <Suspense fallback={<div className="fixed inset-0 flex items-center justify-center bg-black/60 backdrop-blur-sm text-white z-[100]">Loading...</div>}>
      <EmailPasswordForm isModal={isModal} />
    </Suspense>
  );
}

"use client";
import React, { useState, useEffect, useRef } from "react";
import { useQuery, useQueryClient } from "@tanstack/react-query";
import Sidebar from "@/components/chat/Sidebar";
import ChatArea from "@/components/chat/ChatArea";
import MessageInput from "@/components/chat/MessageInput";
import { StreamClient } from "@/lib/streamClient";
import AuthGuard from "@/components/AuthGuard";

export default function Home() {
  const queryClient = useQueryClient();
  const [activeConversationId, setActiveConversationId] = useState(null);

  // Streaming state
  const [isGenerating, setIsGenerating] = useState(false);
  const [streamingContent, setStreamingContent] = useState("");
  const [streamingMsgId, setStreamingMsgId] = useState(null);
  const streamClientRef = useRef(null);

  // Fetch messages for active conversation
  const { data: conversationData, isLoading: isLoadingMessages } = useQuery({
    queryKey: ["conversation", activeConversationId],
    queryFn: async () => {
      if (!activeConversationId) return { messages: [] };
      const res = await window.fetchWithAuth(`/api/conversations/${activeConversationId}`);
      if (!res.ok) throw new Error("Failed to fetch conversation");
      return res.json();
    },
    enabled: !!activeConversationId,
  });

  const messages = conversationData?.messages || [];

  const handleNewChat = () => {
    setActiveConversationId(null);
    setStreamingContent("");
  };

  const handleSelectConversation = (id) => {
    if (isGenerating) return; // Prevent switching while generating
    setActiveConversationId(id);
    setStreamingContent("");
  };

  const handleStop = () => {
    if (streamClientRef.current) {
      streamClientRef.current.abort();
      setIsGenerating(false);
    }
  };

  const handleSendMessage = async (content, uploadedText) => {
    setIsGenerating(true);
    setStreamingContent("");
    const tempId = `temp_${Date.now()}`;
    setStreamingMsgId(tempId);

    // Optimistically update the UI with user message
    const userMsg = { id: `user_${Date.now()}`, role: "user", content: content };
    if (uploadedText) {
      userMsg.content = `Attached Document Context:\n${uploadedText}\n\nUser Message: ${content}`;
    }

    // If we have an active conversation, append to it in cache
    if (activeConversationId) {
      queryClient.setQueryData(["conversation", activeConversationId], (old) => {
        if (!old) return { messages: [userMsg] };
        return { ...old, messages: [...old.messages, userMsg] };
      });
    }

    const payload = {
      conversation_id: activeConversationId,
      content,
      uploaded_text: uploadedText
    };

    const client = new StreamClient(
      "/api/messages",
      // onChunk
      (chunkText) => {
        setStreamingContent((prev) => prev + chunkText);
      },
      // onMeta (Server gives us the conversation_id, crucial for lazy init)
      (meta) => {
        if (meta.conversation_id && !activeConversationId) {
          setActiveConversationId(meta.conversation_id);
          // Invalidate sidebar to show the new chat
          queryClient.invalidateQueries(["conversations"]);
        }
      },
      // onError
      (error) => {
        console.error("Stream Error:", error);
        setIsGenerating(false);
        // Refresh to show failure message saved in DB
        if (activeConversationId) queryClient.invalidateQueries(["conversation", activeConversationId]);
      },
      // onDone
      () => {
        setIsGenerating(false);
        // Fully invalidate to pull the final assistant message from DB with accurate tokens/model
        if (activeConversationId) queryClient.invalidateQueries(["conversation", activeConversationId]);
      }
    );

    streamClientRef.current = client;
    client.connect(payload);
  };

  // Combine DB messages with currently streaming message
  const displayMessages = [...messages];
  if (isGenerating) {
    displayMessages.push({
      id: streamingMsgId,
      role: "assistant",
      content: streamingContent,
      // Temporarily hide metadata until it's finished and fetched from DB
    });
  }

  return (
    <AuthGuard>
      <div className="flex h-screen bg-gray-950 text-gray-100 font-sans overflow-hidden">
        <Sidebar 
          activeConversationId={activeConversationId} 
          onSelectConversation={handleSelectConversation}
          onNewChat={handleNewChat}
        />

        <div className="flex-1 flex flex-col min-w-0 bg-[#0d1117]">
          {/* Header */}
          <header className="h-14 border-b border-gray-800 flex items-center px-6 shrink-0 bg-gray-900/50 backdrop-blur-sm z-10">
            <h1 className="text-lg font-semibold bg-gradient-to-r from-blue-400 to-emerald-400 bg-clip-text text-transparent">
              OmniAI
            </h1>
            {activeConversationId && (
              <span className="ml-4 px-2 py-1 bg-gray-800 text-xs rounded text-gray-400 font-mono border border-gray-700 shadow-inner">
                {activeConversationId.substring(0,8)}...
              </span>
            )}
          </header>

          <ChatArea 
            messages={displayMessages} 
            isGenerating={isGenerating} 
          />

          <MessageInput 
            onSendMessage={handleSendMessage} 
            isGenerating={isGenerating}
            onStop={handleStop}
          />
        </div>
      </div>
    </AuthGuard>
  );
}
